mapper.update:
UPDATE PTL_SEC_POSITION
SET AMOUNT = AMOUNT + #{amount},
UPDATE_TIME=#{updateTime, jdbcType=TIMESTAMP}
WHERE BRANCH = #{branch}
       AND SEC_ACCT_ID = #{secAcctId}
       AND CDATE = #{cdate}
       AND HODING_TYPE = #{hodingType}
       AND INV_AIM = #{invAim}
       AND PORTFOLIO_ID = #{portfolioId}
       AND FINPROD_ID = #{finprodId}

mapper.insert:
INSERT INTO PTL_SEC_POSITION_FLOW
(SEQNO, PORTFOLIO_ID, SEC_ACCT_ID, FINPROD_ID, BRANCH, HODING_TYPE, CDATE, CCY, AMOUNT,
P_FINPROD_ID, TRADE_ID, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, INV_AIM)
select '${seqNo}', PORTFOLIO_ID, SEC_ACCT_ID, FINPROD_ID, BRANCH, HODING_TYPE, #{mDate, jdbcType=DATE}, CCY,

    AMOUNT*-1,


    AMOUNT,

P_FINPROD_ID, TRADE_ID, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, INV_AIM
from PTL_SEC_POSITION_FLOW
where
TRADE_ID = #{tradeId,jdbcType=VARCHAR}
AND HODING_TYPE = #{holdingType}
AND CDATE = #{vDate, jdbcType=DATE}
AND FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
